SourceCode.Declaration:
/// <summary>
/// Interchangeable group: a set of items (RSMItemSubstitutionGroupMember) that
/// can stand in for one another, each measured by an equivalent quantity per
/// case. The generic layer under RSMItemSubstitution: it applies to every
/// customer whose CustTable.RSMSubstitutionPolicy is Standard, after that
/// customer's own rules and the explicit all-customer rules.
/// Ratio between two members = EquivQty(ordered) / EquivQty(substitute).
/// </summary>
public class RSMItemSubstitutionGroup extends common
{
}

Method.Source:
public static RSMItemSubstitutionGroup find(Num _groupId, boolean _forUpdate = false)
{
    RSMItemSubstitutionGroup grp;
    grp.selectForUpdate(_forUpdate);
    if (_groupId)
    {
        select firstonly grp where grp.GroupId == _groupId;
    }
    return grp;
}

public boolean isActive(TransDate _asOf = systemDateGet())
{
    return (!this.ValidFrom || this.ValidFrom <= _asOf)
        && (!this.ValidTo   || this.ValidTo   >= _asOf);
}

/// <summary>
/// The active group that holds both items, as [GroupId, ratio, PriceBasis]
/// (ratio = substitute units per ordered unit), or conNull() when none does.
/// When several groups hold the pair, the one where the substitute ranks
/// highest (lowest Sequence) wins. Mirrors Subs.groupRules in the web app.
/// Callers check the customer's policy first: groups only serve Standard.
/// </summary>
public static container match(ItemId _orderedItemId, ItemId _substituteItemId, TransDate _asOf = systemDateGet())
{
    RSMItemSubstitutionGroupMember fromM, toM;
    RSMItemSubstitutionGroup       grp;

    while select toM
        order by toM.Sequence
        where toM.ItemId == _substituteItemId
    join fromM
        where fromM.GroupId == toM.GroupId
           && fromM.ItemId  == _orderedItemId
    join grp
        where grp.GroupId == toM.GroupId
    {
        if (grp.isActive(_asOf) && fromM.EquivQty > 0 && toM.EquivQty > 0)
        {
            return [grp.GroupId, fromM.EquivQty / toM.EquivQty, grp.PriceBasis];
        }
    }
    return conNull();
}
